use std::{fs,path::Path,sync::Arc,time::Instant};
use serde_json::{Value,json};
#[path="support/perf.rs"]mod perf;
#[global_allocator]static ALLOCATOR:zopro_prover::zopro_core::alloc::Allocator=zopro_prover::zopro_core::alloc::Allocator;
const BLOCKS:usize=7;const ROUNDS:usize=17;const STAGES:usize=BLOCKS*2;
fn allowed()->Vec<usize>{unsafe{let mut mask:libc::cpu_set_t=std::mem::zeroed();assert_eq!(libc::sched_getaffinity(0,std::mem::size_of_val(&mask),&mut mask),0);(0..libc::CPU_SETSIZE as usize).filter(|&i|libc::CPU_ISSET(i,&mask)).collect()}}
fn workers()->Vec<Value>{let mut rows=rayon::broadcast(|_|json!({"index":rayon::current_thread_index().unwrap(),"tid":unsafe{libc::syscall(libc::SYS_gettid)},"allowed":allowed()}));rows.sort_by_key(|x|x["index"].as_u64().unwrap());rows}
fn main()->Result<(),Box<dyn std::error::Error>>{
 let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),7);let image=&args[1];let request=fs::read_to_string(&args[2])?;let out=Path::new(&args[3]);let repetition:usize=args[4].parse()?;assert!(repetition<3);let mode=args[5].as_str();assert!(["paired","a","b"].contains(&mode));let named_block:usize=args[6].parse()?;assert!(named_block<BLOCKS);if mode=="paired"{assert_eq!(named_block,0);}let cpus=allowed();let count=rayon::current_num_threads();assert!([16,32].contains(&count));assert_eq!(cpus,(0..count).collect::<Vec<_>>());
 let file=fs::File::open(image)?;let mapping=unsafe{memmap2::Mmap::map(&file)?};drop(file);let prover=zopro_prover::Prover::load_image(Arc::new(mapping))?;let mut sdk=zopro_zolana::Prover::new(prover)?;let address=std::ptr::addr_of!(sdk)as usize;let before=workers();assert_eq!(before.len(),count);for w in &before{assert_eq!(w["allowed"],json!(cpus));}
 let mut public_len=0;for _ in 0..3{let proof=sdk.prove(&request)?;assert_eq!(proof.proof.len(),164);public_len=proof.public_inputs.len();std::hint::black_box(proof);}
 let mut samples=vec![0f64;STAGES*ROUNDS];let mut exports:Vec<([u8;164],Vec<u8>)>=(0..STAGES).map(|_|([0;164],vec![0;public_len])).collect();let mut records=Vec::with_capacity(STAGES);let mut last=None;let mut stage=0;
 for block in 0..BLOCKS{if mode!="paired"&&block!=named_block{continue;}let labels=if(block+repetition)%2==0{["a","b"]}else{["b","a"]};for label in labels{if mode!="paired"&&label!=mode{continue;}assert_eq!(std::ptr::addr_of!(sdk)as usize,address);
  let usage0=perf::Usage::now()?;let started=Instant::now();for round in 0..ROUNDS{let started=Instant::now();let proof=sdk.prove(&request)?;samples[stage*ROUNDS+round]=started.elapsed().as_secs_f64()*1000.;last=Some(proof);}let loop_ms=started.elapsed().as_secs_f64()*1000.;let usage1=perf::Usage::now()?;
  let proof=last.take().unwrap();assert_eq!(proof.proof.len(),164);assert_eq!(proof.public_inputs.len(),public_len);exports[stage].0.copy_from_slice(&proof.proof);exports[stage].1.copy_from_slice(&proof.public_inputs);drop(proof);records.push((block,label,loop_ms,usage0,usage1));stage+=1;
 }}assert_eq!(stage,if mode=="paired"{STAGES}else{1});let after=workers();assert_eq!(before,after);assert_eq!(std::ptr::addr_of!(sdk)as usize,address);fs::create_dir_all(out)?;
 println!("CONTEXT {}",json!({"pid":std::process::id(),"mode":mode,"repetition":repetition,"workers":count,"priming":3,"one_sdk_object":true,"same_worker_receipts":true,"before":before,"after":after,"sample_capacity":samples.len(),"export_capacity":exports.len(),"public_bytes":public_len}));
 for(i,(block,label,loop_ms,u0,u1))in records.into_iter().enumerate(){let directory=out.join("transfer_confidential_1_2");fs::create_dir_all(&directory)?;let proof_path=directory.join(format!("b{block}-{label}.proof"));let public_path=proof_path.with_extension("public");fs::write(&proof_path,exports[i].0)?;fs::write(&public_path,&exports[i].1)?;let mut row=u1.difference(&u0);row["block"]=json!(block);row["label"]=json!(label);row["repetition"]=json!(repetition);row["workers"]=json!(count);row["mode"]=json!(mode);row["rounds"]=json!(ROUNDS);row["loop_wall_ms"]=json!(loop_ms);row["samples_ms"]=json!(&samples[i*ROUNDS..(i+1)*ROUNDS]);row["proof_path"]=json!(proof_path);row["public_path"]=json!(public_path);println!("STAGE {row}");}
 Ok(())
}
